<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BST · isBST interactive</title>
<style>
*{box-sizing:border-box}body{margin:0;padding:14px;font-family:system-ui,"Segoe UI",sans-serif;background:#f2f6fb;color:#17324d}main{max-width:980px;margin:auto}section{background:white;padding:14px;border:1px solid #d7e0ec;border-radius:15px;margin-bottom:12px}h2{margin:0 0 8px;font-size:21px}p{line-height:1.45;color:#526785}small{color:#687b92}svg{display:block;width:100%;height:auto;background:#f8fafc;border-radius:10px}button{padding:10px 16px;margin:4px;border:1px solid #9aafca;background:white;border-radius:8px;cursor:pointer;color:#183954;font-weight:700}button:disabled{opacity:.36;cursor:default}button.primary{background:#196aab;color:white}input{width:100%;accent-color:#196aab}.legend{font-size:13px;color:#53687f;display:flex;gap:13px;flex-wrap:wrap;margin:10px 0}.legend b{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}#status{padding:12px;border-radius:9px;background:#eaf2fb;margin-top:8px;min-height:70px}#status strong{display:block}pre{background:#111c2c;color:#ecf2ff;border-radius:10px;padding:14px;overflow:auto;line-height:1.5}summary{font-weight:700;cursor:pointer}summary+*{margin-top:12px}.row{display:flex;justify-content:space-between;align-items:center;gap:10px}.row span{font-variant-numeric:tabular-nums}.java-step-panel{margin:12px 0;border:1px solid #c7d7ea;border-radius:10px;overflow:hidden}.java-step-title{padding:9px 12px;background:#eaf2fb;color:#193956;font-weight:700}.java-step-panel pre{margin:0;border-radius:0;padding:8px 4px;line-height:1.45;font-size:13px}.java-line{display:block;white-space:pre;padding:2px 10px;border-left:4px solid transparent}.java-line.active-line{background:#20496f;border-left-color:#5bd0ff;color:#fff}.java-line.context-line{background:#202f48;border-left-color:#8a9ebd}.java-line-number{display:inline-block;width:24px;color:#879ab6;user-select:none}.active-line .java-line-number{color:#bcecff}#java-step-note{margin:0;padding:8px 12px;background:#f1f7fd;font-size:13px;color:#415d7d}@media(max-width:600px){.java-step-panel pre{font-size:11px}.java-line{padding-left:4px;padding-right:3px}}
</style></head><body><main><section>
<div class="row"><h2>isBST · 交互式递归检查</h2><span id="counter">1 / 22</span></div>
<div class="legend"><span><b style="background:#1679c5"></b>Call</span><span><b style="background:#159867"></b>Return</span><span><b style="background:#d68d24"></b>low / high 竖虚线</span></div>
<svg id="figure" viewBox="0 0 960 594" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="三层 BST 的递归检查步骤">
<defs><marker id="bluehead" markerWidth="10" markerHeight="10" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="none" stroke="#1679c5" stroke-width="1.5"/></marker><marker id="greenhead" markerWidth="10" markerHeight="10" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="none" stroke="#159867" stroke-width="1.5"/></marker></defs>
<g id="bounds"></g><g id="links"></g><g id="activeArrow"></g><g id="circles"></g><g id="nil"></g>
<text x="24" y="36" font-size="21" font-weight="700" fill="#18324b">当前区间</text><text id="range" x="210" y="36" font-size="22" fill="#136e9b" font-weight="700"></text>
<text x="24" y="573" font-size="16" fill="#5c7190">灰线是 Tree Edge · 每一步只显示一条执行箭头</text></svg>
<div class="java-step-panel"><div class="java-step-title">Java code · highlighted for each step</div><pre aria-label="Step-by-step Java source"><code id="java-code"></code></pre><p id="java-step-note" aria-live="polite"></p></div>
