<div><button id="prev">← 上一步</button><button id="next" class="primary">下一步 →</button><button id="reset">重置</button></div><input id="slider" type="range" min="0" max="21" step="1" value="0" aria-label="跳转到步骤">
</section>
</main><script>
(function(){
"use strict";
var NS="http://www.w3.org/2000/svg";
var nodes=[
{k:20,x:480,y:160,p:null,lo:null,hi:null},{k:10,x:270,y:294,p:20,lo:null,hi:20},{k:30,x:690,y:294,p:20,lo:20,hi:null},
{k:5,x:165,y:429,p:10,lo:null,hi:10},{k:15,x:375,y:429,p:10,lo:10,hi:20},{k:25,x:585,y:429,p:30,lo:20,hi:30},{k:35,x:795,y:429,p:30,lo:30,hi:null}
],map={};nodes.forEach(function(n){map[n.k]=n});
var steps=[
["call",20,null,"Call isBST(20)","先检查 Root 20，当前没有 Bounds"],
["call",10,20,"Call isBST(10)","10 < 20，继续检查 Left"],
["call",5,10,"Call isBST(5)","5 < 10，当前 Key 通过"],
["null",5,"left","5.left == null → true","空 Subtree 不违反 BST Property"],
["null",5,"right","5.right == null → true","空 Subtree 返回 true，不是 Output"],
["return",5,10,"5 → return true","5 的左右 Subtree 都通过"],
["call",15,10,"Call isBST(15)","10 < 15 < 20，保留所有 Ancestor Bounds"],
["null",15,"left","15.left == null → true","空 Subtree 返回 true"],
["null",15,"right","15.right == null → true","空 Subtree 返回 true"],
["return",15,10,"15 → return true","15 检查完毕，回到 10"],
["return",10,20,"10 → return true","整个 Left Subtree 通过，回到 20"],
["call",30,20,"Call isBST(30)","开始检查 Right Subtree"],
["call",25,30,"Call isBST(25)","20 < 25 < 30，当前 Key 通过"],
["null",25,"left","25.left == null → true","空 Subtree 返回 true"],
["null",25,"right","25.right == null → true","空 Subtree 返回 true"],
["return",25,30,"25 → return true","25 检查完毕，回到 30"],
["call",35,30,"Call isBST(35)","35 > 30，当前 Key 通过"],
["null",35,"left","35.left == null → true","空 Subtree 返回 true"],
["null",35,"right","35.right == null → true","空 Subtree 返回 true"],
["return",35,30,"35 → return true","35 检查完毕，回到 30"],
["return",30,20,"30 → return true","整个 Right Subtree 通过，回到 20"],
["return",20,null,"isBST(root) → true","两边都通过，整个 BST 有效"]
];
var idx=0;
// The Java source is rendered once as distinct, numbered lines; each trace step highlights its matching statement.
var javaLines=[
'public boolean isBST() {',
'    return isBST(root);',
'}',
'private static boolean isBST(Node x) {',
'    return isBST(x, null, null);',
'}',
'private static boolean isBST(Node x, Integer low, Integer high) {',
'    if (x == null) return true;',
'    if (low != null && x.key <= low) return false;',
'    if (high != null && x.key >= high) return false;',
'    return isBST(x.left, low, x.key)',
'        && isBST(x.right, x.key, high);',
'}'
]
// [current statements, related statements]. Call steps also show the bounds checks run on entry.
var codeTrace=[
[[2,5],[9,10]],[[11],[9,10]],[[11],[9,10]],[[8],[11]],[[8],[12]],[[11,12],[]],
[[12],[9,10]],[[8],[11]],[[8],[12]],[[11,12],[]],[[11,12],[]],
[[12],[9,10]],[[11],[9,10]],[[8],[11]],[[8],[12]],[[11,12],[]],
[[12],[9,10]],[[8],[11]],[[8],[12]],[[11,12],[]],[[11,12],[]],[[11,12],[]]
]
var codeRoot=document.getElementById('java-code'),codeRows=[];
javaLines.forEach(function(source,i){
  var row=document.createElement('span'),lineNumber=document.createElement('span'),lineText=document.createElement('span');
  row.className='java-line';lineNumber.className='java-line-number';lineNumber.textContent=String(i+1);
  lineText.textContent=source;row.appendChild(lineNumber);row.appendChild(lineText);codeRoot.appendChild(row);codeRows.push(row);
});
function renderCode(){
  var trace=codeTrace[idx],current=trace[0],context=trace[1];
  codeRows.forEach(function(row,i){var line=i+1;row.className='java-line'+(current.indexOf(line)!==-1?' active-line':context.indexOf(line)!==-1?' context-line':'')});
  var s=steps[idx],kind=s[0];
  document.getElementById('java-step-note').textContent=
    'Blue = executing '+current.map(function(i){return 'L'+i}).join(', ')+
    (context.length?' · Darker = related '+context.map(function(i){return 'L'+i}).join(', '):'')+
    (kind==='null'?' · Base case returns true to the caller':kind==='return'?' · The recursive calls have returned':' · Check the current node and its inherited bounds');
}
function mk(tag,attrs,val){var el=document.createElementNS(NS,tag);Object.keys(attrs||{}).forEach(function(k){el.setAttribute(k,attrs[k])});if(val!==undefined)el.textContent=val;return el}
function wipe(id){var e=document.getElementById(id);e.replaceChildren();return e}
function path(a,b,kind){var sx=a.x,sy=a.y+(kind==="call"?32:-32),ex=b.x,ey=b.y+(kind==="call"?-32:32),sign=ex>sx?1:-1;return "M"+sx+" "+sy+" Q"+((sx+ex)/2+(kind==="call"?-48:48)*sign)+" "+((sy+ey)/2)+" "+ex+" "+ey}
function render(){
var s=steps[idx],kind=s[0],n=map[s[1]],ref=s[2],g=wipe("bounds"),l=wipe("links"),ar=wipe("activeArrow"),cir=wipe("circles"),nul=wipe("nil");
var left=n.lo===null?65:map[n.lo].x,right=n.hi===null?900:map[n.hi].x;
g.appendChild(mk("rect",{x:left,y:78,width:right-left,height:446,fill:"#e0f2fe","fill-opacity":.5}));
if(n.lo!==null){g.appendChild(mk("line",{x1:left,x2:left,y1:75,y2:520,stroke:"#d68d24","stroke-width":3,"stroke-dasharray":"8 8"}));g.appendChild(mk("text",{x:left+9,y:95,fill:"#975711","font-size":17,"font-weight":700},"low = "+n.lo))}
if(n.hi!==null){g.appendChild(mk("line",{x1:right,x2:right,y1:75,y2:520,stroke:"#d68d24","stroke-width":3,"stroke-dasharray":"8 8"}));g.appendChild(mk("text",{x:right-9,y:116,fill:"#975711","font-size":17,"font-weight":700,"text-anchor":"end"},"high = "+n.hi))}
nodes.forEach(function(x){if(x.p!==null){var p=map[x.p];l.appendChild(mk("line",{x1:p.x,y1:p.y+27,x2:x.x,y2:x.y-27,stroke:"#9baec2","stroke-width":3.4,"stroke-linecap":"round"}))}});
if((kind==="call"||kind==="return")&&ref!==null){var from=kind==="call"?map[ref]:n,to=kind==="call"?n:map[ref];ar.appendChild(mk("path",{d:path(from,to,kind),fill:"none",stroke:kind==="call"?"#1679c5":"#159867","stroke-width":5,"stroke-linecap":"round","stroke-dasharray":kind==="return"?"9 7":"none","marker-end":kind==="call"?"url(#bluehead)":"url(#greenhead)"}))}
var past=steps.slice(0,idx+1);var returned=new Set(past.filter(function(q){return q[0]==="return"}).map(function(q){return q[1]})),called=new Set(past.filter(function(q){return q[0]==="call"}).map(function(q){return q[1]}));
nodes.forEach(function(x){var active=x.k===n.k;cir.appendChild(mk("circle",{cx:x.x,cy:x.y,r:active?39:34,fill:active?"#fef3c7":returned.has(x.k)?"#d5f5e3":called.has(x.k)?"#dceeff":"#fff",stroke:active?"#d97706":returned.has(x.k)?"#21976b":"#638cb5","stroke-width":active?4:2.7}));cir.appendChild(mk("text",{x:x.x,y:x.y+9,"font-size":27,"font-weight":700,"text-anchor":"middle",fill:"#1c354d"},x.k))});
if(kind==="null"){var x=n.x+(ref==="left"?-65:65),y=530;nul.appendChild(mk("path",{d:"M"+x+" "+(y-19)+" Q"+(x+(ref==="left"?38:-38))+" "+(y-57)+" "+n.x+" "+(n.y+33),fill:"none",stroke:"#159867","stroke-width":4.5,"stroke-dasharray":"8 7","marker-end":"url(#greenhead)"}));nul.appendChild(mk("rect",{x:x-58,y:y-20,width:116,height:43,rx:12,fill:"#d5f5e3",stroke:"#159867","stroke-width":2}));nul.appendChild(mk("text",{x:x,y:y+7,fill:"#166343","text-anchor":"middle","font-size":17,"font-weight":700},"null → true"))}
if(idx===steps.length-1){nul.appendChild(mk("text",{x:480,y:540,"text-anchor":"middle","font-size":24,fill:"#159867","font-weight":700},"isBST(root) = true"))}
document.getElementById("range").textContent=(n.lo===null?"−∞":n.lo)+" < key < "+(n.hi===null?"+∞":n.hi);
document.getElementById("action").textContent=s[3];document.getElementById("detail").textContent=s[4];
document.getElementById("counter").textContent=(idx+1)+" / "+steps.length;
document.getElementById("prev").disabled=idx===0;document.getElementById("next").disabled=idx===steps.length-1;
document.getElementById("reset").disabled=idx===0;document.getElementById("slider").value=idx;renderCode();
}
document.getElementById("prev").onclick=function(){idx=Math.max(0,idx-1);render()};
document.getElementById("next").onclick=function(){idx=Math.min(idx+1,steps.length-1);render()};
document.getElementById("reset").onclick=function(){idx=0;render()};
document.getElementById("slider").oninput=function(e){idx=Number(e.target.value);render()};
document.addEventListener("keydown",function(e){if(document.activeElement&&document.activeElement.tagName==="INPUT")return;if(e.key==="ArrowRight"){idx=Math.min(idx+1,steps.length-1);render()}if(e.key==="ArrowLeft"){idx=Math.max(0,idx-1);render()}});
render();
})();
</script></body></html>
```

`Call` = 函数调用　｜　`Return` = Boolean 返回　｜　`Return ≠ Output`
